
import * as THREE from "three";

var areaTexture = new THREE.Texture();
const areaTextureImage = new Image();
areaTextureImage.src = `data:image/png;base64,`
areaTextureImage.onload = function () {

    // assigning data to HTMLImageElement.src is asynchronous (see #15162)
    areaTexture.needsUpdate = true;

};
areaTexture.image = areaTextureImage;

const materialC = new THREE.SpriteMaterial({   map: areaTexture, fog: true, sizeAttenuation: false, depthTest: false });

class LoadingSprite extends THREE.Sprite{
    constructor(){
        super(materialC);
        this.scale.set(0.03,0.03,0.03);
    }
}

export default LoadingSprite;